'use client';

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { api } from '@/lib/api';
import { Users, ShoppingCart, CalendarDays, TrendingUp } from 'lucide-react';
import Link from 'next/link';

const AdminHome = () => {
  const [stats, setStats] = useState({
    totalUsers: 0,
    totalOrders: 0,
    totalReservations: 0,
    totalRevenue: 0
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchStats = async () => {
      try {
        // Fetch admin statistics
        const [usersRes, ordersRes, reservationsRes] = await Promise.all([
          api.get('/user'),
          api.get('/orders'),
          api.get('/reservations')
        ]);

        setStats({
          totalUsers: usersRes.data.meta?.total || 0,
          totalOrders: ordersRes.data.length || 0,
          totalReservations: reservationsRes.data.length || 0,
          totalRevenue: ordersRes.data.reduce((sum: number, order: any) => sum + order.totalPrice, 0) || 0
        });
      } catch (error) {
        console.error('Error fetching stats:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchStats();
  }, []);

  if (loading) {
    return <div className="flex justify-center items-center min-h-screen">Đang tải...</div>;
  }

  return (
    <div className="container mx-auto py-8 px-4">
      <div className="mb-8">
        <h1 className="text-3xl font-bold text-gray-900 mb-2">Bảng điều khiển Admin</h1>
        <p className="text-gray-600">Quản lý nhà hàng của bạn</p>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Tổng người dùng</CardTitle>
            <Users className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{stats.totalUsers}</div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Tổng đơn hàng</CardTitle>
            <ShoppingCart className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{stats.totalOrders}</div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Tổng đặt bàn</CardTitle>
            <CalendarDays className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{stats.totalReservations}</div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Doanh thu</CardTitle>
            <TrendingUp className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{stats.totalRevenue.toLocaleString('vi-VN')} VND</div>
          </CardContent>
        </Card>
      </div>

      {/* Quick Actions */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        <Card>
          <CardHeader>
            <CardTitle>Quản lý menu</CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-gray-600 mb-4">Thêm, sửa, xóa các món trong menu</p>
            <Link href="/admin/menu">
              <Button className="w-full">Quản lý Menu</Button>
            </Link>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Quản lý đơn hàng</CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-gray-600 mb-4">Theo dõi và xử lý đơn hàng</p>
            <Link href="/admin/orders">
              <Button className="w-full">Quản lý Đơn hàng</Button>
            </Link>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Quản lý đặt bàn</CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-gray-600 mb-4">Xác nhận và quản lý đặt bàn</p>
            <Link href="/admin/reservations">
              <Button className="w-full">Quản lý Đặt bàn</Button>
            </Link>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Quản lý người dùng</CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-gray-600 mb-4">Quản lý tài khoản người dùng</p>
            <Link href="/admin/users">
              <Button className="w-full">Quản lý Người dùng</Button>
            </Link>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Mã QR</CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-gray-600 mb-4">Tạo mã QR cho bàn</p>
            <Link href="/admin/qr">
              <Button className="w-full">Tạo QR</Button>
            </Link>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Báo cáo</CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-gray-600 mb-4">Xem báo cáo doanh thu</p>
            <Link href="/admin/reports">
              <Button className="w-full">Xem Báo cáo</Button>
            </Link>
          </CardContent>
        </Card>
      </div>
    </div>
  );
};

export default AdminHome;
